examples.code:
@* language "Markdown" makes the Preview/Edit toggle appear in the block header *@
<TmNotionCodeBlock Content="@_markdown"
                   OnCodeSaved="code => _markdown.Code = code" />

@code {
    private CodeBlockContent _markdown = new()
    {
        Language = "Markdown",
        Code = """
            | Name | Status |
            | :--- | ---: |
            | CF26 | Ready |
            """
    };
}
